WITH filtered AS (SELECT id, account_id, txn_type, amount, txn_time, merchant, DATE_TRUNC('year', txn_time) AS txn_time_period FROM transactions WHERE merchant IS NOT DISTINCT FROM '7-Eleven' AND txn_time >= DATE '2023-10-18'), with_dims AS (SELECT a.id, a.account_id, a.txn_time, a.merchant, a.txn_time_period, p.balance, p.opened_date, p.account_type FROM filtered a LEFT JOIN accounts p ON a.account_id = p.id WHERE p.opened_date < '2025-01-01'), with_dims_transactions AS (SELECT a.*, p.status FROM with_dims a LEFT JOIN accounts p ON a.account_id = p.id), metrics AS (SELECT *, LEAD(balance) OVER (PARTITION BY status ORDER BY txn_time_period, id) AS next_balance, LAG(balance) OVER (PARTITION BY status ORDER BY txn_time_period, id) AS prev_balance, ROW_NUMBER() OVER (PARTITION BY status ORDER BY txn_time_period, id) AS seq_no, MAX(balance) OVER (PARTITION BY status ORDER BY CAST(txn_time_period AS BIGINT) RANGE BETWEEN 2592000 PRECEDING AND CURRENT ROW) AS balance_max_30d FROM with_dims_transactions) SELECT s.id, s.account_id, s.txn_time, s.balance, s.opened_date, s.account_type, s.prev_balance, s.balance_max_30d, CASE WHEN account_type RLIKE '^(CREDIT|LOAN)$' THEN 'OTHER_ZONE' WHEN account_type RLIKE '^(SAVINGS|CHECKING)$' THEN 'EXTENDED' ELSE 'GROUP_A' END AS account_type_zone, (SELECT SUM(t2.amount) FROM transactions t2 WHERE t2.account_id = s.account_id) AS sum_transaction_amount FROM metrics s ORDER BY account_type DESC NULLS FIRST, opened_date;
